package africa.growtogether.platform.ewe.task; import static africa.growtogether.platform.ewe.task.TaskDtos.*; import africa.growtogether.platform.common.security.EnterpriseIdentityContext; import africa.growtogether.platform.ewe.integration.EweAuditRecorder; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class WorkflowTaskService { private final WorkflowTaskRepository tasks; private final WorkflowTaskEventRepository events; private final WorkflowRoutingRuleRepository rules; private final EnterpriseIdentityContext identity; private final EweAuditRecorder audit; public WorkflowTaskService(WorkflowTaskRepository t,WorkflowTaskEventRepository e,WorkflowRoutingRuleRepository r,EnterpriseIdentityContext identity,EweAuditRecorder audit){tasks=t;events=e;rules=r;this.identity=identity;this.audit=audit;} private UUID tenant(){return identity.tenantId();}
 @Transactional public TaskView create(CreateTask c){WorkflowTask t=new WorkflowTask(c.instanceId(),c.taskKey(),c.name(),c.taskType());applyAssignment(t,c.assignmentType(),c.assignmentValue());t.setSla(c.dueAt(),c.escalationAt());tasks.save(t);event(t,"TASK_CREATED",null);return TaskView.from(t);} @Transactional(readOnly=true) public List<TaskView> byInstance(UUID id){return tasks.findAllByInstanceIdAndTenantIdOrderByCreatedAtAsc(id,tenant()).stream().map(TaskView::from).toList();}
 @Transactional public TaskView claim(UUID id,UUID user){WorkflowTask t=get(id);t.claim(user);event(t,"TASK_CLAIMED",user);return TaskView.from(tasks.save(t));} @Transactional public TaskView start(UUID id){WorkflowTask t=get(id);t.start();event(t,"TASK_STARTED",null);return TaskView.from(tasks.save(t));} @Transactional public TaskView complete(UUID id,CompleteTask c){WorkflowTask t=get(id);t.complete(c.outcome(),c.comment());event(t,"TASK_COMPLETED",identity.userId());audit.task("EWE.TASK.COMPLETED",t.getId(),"Workflow task completed");return TaskView.from(tasks.save(t));} @Transactional public TaskView decide(UUID id,Decision c){WorkflowTask t=get(id);t.decide(c.decision(),c.comment());event(t,"TASK_DECIDED",identity.userId());audit.task("EWE.TASK.DECIDED",t.getId(),"Workflow task decision recorded");return TaskView.from(tasks.save(t));} @Transactional public TaskView delegate(UUID id,Delegate c){WorkflowTask t=get(id);t.delegate(c.fromUserId(),c.toUserId());event(t,"TASK_DELEGATED",c.fromUserId());return TaskView.from(tasks.save(t));} @Transactional public TaskView escalate(UUID id,UUID to){WorkflowTask t=get(id);t.escalate(to);event(t,"TASK_ESCALATED",null);return TaskView.from(tasks.save(t));}
 @Transactional public void processEscalations(){var open=List.of(TaskStatus.ASSIGNED,TaskStatus.CLAIMED,TaskStatus.IN_PROGRESS);for(WorkflowTask t:tasks.findAllByTenantIdAndEscalationAtBeforeAndTaskStatusIn(tenant(),Instant.now(),open)){t.escalate(null);tasks.save(t);event(t,"TASK_ESCALATED",null);}}
 @Transactional public UUID createRule(CreateRoutingRule c){WorkflowRoutingRule r=new WorkflowRoutingRule(c.workflowDefinitionId(),c.taskKey(),c.priority(),c.conditionExpression(),c.assignmentType(),c.assignmentValue());return rules.save(r).getId();}
 private WorkflowTask get(UUID id){return tasks.findByIdAndTenantId(id,tenant()).orElseThrow(()->new IllegalArgumentException("Workflow task not found"));} private void applyAssignment(WorkflowTask t,AssignmentType type,String value){if(type==null||type==AssignmentType.UNASSIGNED)return;switch(type){case USER->t.assignUser(UUID.fromString(value));case ROLE->t.assignRole(value);case GROUP->t.assignGroup(value);case EXPRESSION->t.assignExpression(value);default->{}}} private void event(WorkflowTask t,String type,UUID actor){events.save(new WorkflowTaskEvent(tenant(),t.getId(),type,actor,"{}"));}}
